    def format_signature(self, **kwargs: Any) -> str:
        """Format the signature (arguments and return annotation) of the object.

        Let the user process it via the ``autodoc-process-signature`` event.
        """
        if self.args is not None:
            # signature given explicitly
            args = "(%s)" % self.args
            retann = self.retann
        else:
            # try to introspect the signature
            try:
                retann = None
                args = self._format_signature()
            except Exception as exc:
                logger.warning(__('error while formatting signature for %s: %s'),
                               self.fullname, exc, type='autodoc')
                return None

        if self.env.config.autodoc_typehints:
            if self.env.config.autodoc_typehints == 'none':
                # strip type hints
                args = stringify_signature(inspect.signature(self.object), show_annotation=False)
                retann = None

        result = self.env.app.emit_firstresult('autodoc-process-signature',
                                               self.objtype, self.fullname,
                                               self.object, self.options, args, retann)
        if result:
            args, retann = result

        if retann:
            return "%s -> %s" % (args, retann)
        else:
            return args
